for number, pairs in product_edits.items():
    edits[f'src/data/products/product-{number}.json'] = pairs

for name, pairs in edits.items():
    path = Path(name)
    raw = path.read_bytes().decode('utf-8')
    newline = '\r\n' if '\r\n' in raw else '\n'
    content = raw.replace('\r\n', '\n')
    for before, after in pairs:
        assert content.count(before) == 1, (name, before, content.count(before))
        content = content.replace(before, after)
    path.write_bytes(content.replace('\n', newline).encode('utf-8'))
print(f'Updated {len(edits)} files with {sum(map(len, edits.values()))} targeted replacements.')
